aits":["practical","wary","observant","understated"],"abilities":[{"name":"Bookkeeping eye","description":"Notices inconsistencies in dates, totals, and identifying marks from years of keeping ferry accounts.","category":"mental"},{"name":"Steady testimony","description":"Once persuaded that someone is listening, can give a clear chronological account of a transaction or record.","category":"social"}]}],"relationships":[{"id":"rel_neris_oren","source_character_id":"chr_neris_vell","target_character_id":"chr_oren_dask","relationship_type":"rival","description":"Neris needs Oren's warrant and weigher's key, while Oren's insistence on proof frustrates her urgent effort to keep Tovan from a wrongful weighing."},{"id":"rel_oren_neris","source_character_id":"chr_oren_dask","target_character_id":"chr_neris_vell","relationship_type":"skeptical ally","description":"Oren initially distrusts Neris's account of the miscast, but her admission of her own rushed verification persuades him to help her audit it."},{"id":"rel_neris_sella","source_character_id":"chr_neris_vell","target_character_id":"chr_sella_morn","relationship_type":"ally","description":"Neris asks Sella to locate the sealed ledger; Sella's oath-bound caution forces Neris to secure the proper warrant instead of demanding an exception."},{"id":"rel_sella_oren","source_character_id":"chr_sella_morn","target_character_id":"chr_oren_dask","relationship_type":"uneasy allies","description":"Sella will not open the sealed stacks without Oren's warrant, while Oren needs her archive knowledge to verify the account."},{"id":"rel_tovan_neris","source_character_id":"chr_tovan_rell","target_character_id":"chr_neris_vell","relationship_type":"wary ally","description":"Tovan trusts Neris with his tally-slip only after she returns to the Gate of Receipts and listens to his account of the mismatch."},{"id":"rel_neris_tovan","source_character_id":"chr_neris_vell","target_character_id":"chr_tovan_rell","relationship_type":"advocate","description":"Neris treats Tovan's tally-slip as evidence rather than a disposable receipt and carries his correction through the counting-houses."}]}
